"""Synthetic GitHub data (group E): five local clones under local-repos/Projects/<name>/ built with synthlib.git_repo
(backdated commits), one manifest row per repo directory (= one repository item), plus gh-api style metadata
(repo.json, issues_and_prs.json) for idetrace-splits and uist26-talk under github.com/divadbaroon/<repo>.meta/."""
import os, sys, json, random, datetime
sys.path.insert(0, os.path.dirname(__file__))
from synthlib import *

g = Gen('github')
OWNER = 'divadbaroon'
PY_GITIGNORE = '__pycache__/\n*.pyc\n.venv/\n.env\n.env.*\n.DS_Store\n.ipynb_checkpoints/\n'


def repo(name, commits, project_ids, notes, remote=True):
    path = os.path.join(g.dir, 'local-repos', 'Projects', name)
    head = git_repo(path, commits, remote=f'https://github.com/{OWNER}/{name}.git' if remote else None)
    last = commits[-1][0]
    g.add(f'local-repos/Projects/{name}', account=f'~/Projects (local clone of github.com/{OWNER}/{name})', date=last, project_ids=project_ids,
          source=f'~/Projects/{name}', modeled_on='authentic/github/local-repos/<path> (local working copy + .git)',
          notes=f'{notes}; branch=main; commits={len(commits)}; first commit={iso(commits[0][0])}')
    os.utime(path, (epoch(last), epoch(last)))
    return head


