QUIET = {('2025-12-22', '2026-01-04'), ('2026-06-29', '2026-07-05'), ('2026-08-03', '2026-08-09')}
WEEK = [('elliptical', 45, 128), ('run', 60, 136), ('ride', 75, 131), ('run', 55, 138), ('elliptical', 40, 126), ('run', 100, 140), ('ride', 90, 129)]


def training_rows(end):
    rnd = random.Random('zone2-log')
    d = datetime.date(2025, 10, 27); rows = []
    end = dt(end).date()
    while d <= datetime.date(2026, 10, 15):
        quiet = any(datetime.date.fromisoformat(a) <= d <= datetime.date.fromisoformat(b) for a, b in QUIET)
        sport, mins, hr = WEEK[d.weekday()]
        skip = rnd.random() < (0.55 if quiet else 0.08)
        block = 1.0 + (0.12 if d >= datetime.date(2026, 8, 17) else 0.0)
        if d == datetime.date(2026, 10, 15):
            vals = d, 'race', 85, 171, 'Bay Area half marathon 1:24:51'
        elif not skip:
            m = int(mins * block * rnd.uniform(0.85, 1.15) * (0.6 if quiet else 1.0))
            if d >= datetime.date(2026, 10, 5): m = int(m * 0.7)  # taper
            vals = d, sport, m, hr + rnd.randint(-4, 4), NOTES.get(d.isoformat(), '')
        else:
            d += datetime.timedelta(days=1); continue
        if d <= end: rows.append(vals)
        d += datetime.timedelta(days=1)
    return 'date,sport,minutes,avg_hr,notes\n' + ''.join(f'{a},{b},{c},{e},{n}\n' for a, b, c, e, n in rows)


