LOG_SESSION = '"""Append a session to data/log.csv: python log_session.py <sport> <minutes> <avg_hr> [notes] [--date YYYY-MM-DD]"""\nimport csv, sys\nfrom datetime import date\n\nSPORTS = {"run", "ride", "elliptical", "race"}\n\n\ndef main(argv):\n    d = date.today().isoformat()\n    if "--date" in argv:\n        i = argv.index("--date"); d = argv[i + 1]; argv = argv[:i] + argv[i + 2:]\n    sport, minutes, hr, *notes = argv\n    assert sport in SPORTS, f"sport must be one of {sorted(SPORTS)}"\n    with open("data/log.csv", "a", newline="") as f:\n        csv.writer(f).writerow([d, sport, int(minutes), int(hr), " ".join(notes)])\n    print(f"logged {d} {sport} {minutes} min @ {hr}")\n\n\nif __name__ == "__main__":\n    main(sys.argv[1:])\n'
HR_ZONES = '"""Heart-rate zones from max HR (196, field test Oct 2025)."""\nMAX_HR = 196\nBOUNDS = [(1, 0.0, 0.60), (2, 0.60, 0.70), (3, 0.70, 0.80), (4, 0.80, 0.90), (5, 0.90, 1.01)]\n\n\ndef zone(hr):\n    f = hr / MAX_HR\n    return next(z for z, lo, hi in BOUNDS if lo <= f < hi)\n\n\nif __name__ == "__main__":\n    for z, lo, hi in BOUNDS:\n        print(f"Z{z}: {round(lo * MAX_HR)}-{round(min(hi, 1) * MAX_HR)} bpm")\n'
WEEKLY = '"""Weekly training hours by sport from a Strava bulk export (activities.csv)."""\nimport sys\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\nSPORT = {"Run": "run", "Ride": "ride", "VirtualRide": "ride", "Workout": "elliptical", "Elliptical": "elliptical"}\n\n\ndef load(path="data/strava/activities.csv"):\n    df = pd.read_csv(path)\n    # the export repeats some headers; pandas suffixes the second copy with .1 (seconds / metres)\n    df["date"] = pd.to_datetime(df["Activity Date"], format="%b %d, %Y, %I:%M:%S %p")\n    df["sport"] = df["Activity Type"].map(SPORT).fillna("other")\n    df["hours"] = df["Moving Time"] / 3600\n    return df\n\n\ndef weekly(df, year=2026):\n    d = df[df.date.dt.year == year]\n    wk = d.groupby([pd.Grouper(key="date", freq="W-MON", label="left", closed="left"), "sport"]).hours.sum().unstack(fill_value=0)\n    wk["total"] = wk.sum(axis=1)\n    return wk.round(2)\n\n\nif __name__ == "__main__":\n    wk = weekly(load(*sys.argv[1:2]))\n    print(wk.tail(12).to_string())\n    ax = wk.drop(columns="total").plot.bar(stacked=True, figsize=(11, 4), width=0.85)\n    ax.axhspan(8, 11, color="green", alpha=0.08, label="8-11 h target")\n    ax.set_xticklabels([d.strftime("%b %d") for d in wk.index], rotation=90, fontsize=7)\n    ax.set_ylabel("hours"); ax.legend(fontsize=8)\n    plt.tight_layout(); plt.savefig("weekly_hours.png", dpi=150)\n    print("wrote weekly_hours.png")\n'
WEEKLY2 = WEEKLY.replace('    ax.axhspan(8, 11', '    ax.plot(range(len(wk)), wk["total"].rolling(4, min_periods=1).mean(), color="black", lw=1.2, label="4-wk avg")\n    ax.axhspan(8, 11')
DECOUP = '"""Aerobic decoupling (Pa:HR drift) for long runs: (EF first half - EF second half) / EF first half."""\nimport json\nfrom pathlib import Path\nimport pandas as pd\nfrom weekly_hours import load\n\n\ndef decoupling(stream, warmup_s=600):\n    t, hr, v = stream["time"], stream["heartrate"], stream["velocity_smooth"]\n    pts = [(ti, h, vi) for ti, h, vi in zip(t, hr, v) if ti >= warmup_s and h and vi > 1.5]  # drop warm-up and stops\n    if len(pts) < 1200:\n        return None\n    mid = len(pts) // 2\n    ef = lambda seg: sum(p[2] for p in seg) / sum(p[1] for p in seg)  # speed per beat\n    a, b = ef(pts[:mid]), ef(pts[mid:])\n    return round(100 * (a - b) / a, 1)\n\n\nif __name__ == "__main__":\n    acts = load()\n    runs = acts[(acts.sport == "run") & (acts["Moving Time"] >= 75 * 60)]\n    rows = []\n    for _, r in runs.iterrows():\n        f = Path(f"data/streams/{r[\'Activity ID\']}.json")\n        if f.exists():\n            d = decoupling(json.load(open(f)))\n            if d is not None:\n                rows.append({"date": r.date.date(), "name": r["Activity Name"], "min": round(r["Moving Time"] / 60), "decoupling_%": d})\n    out = pd.DataFrame(rows).sort_values("date")\n    out["ok"] = out["decoupling_%"] < 5\n    print(out.to_string(index=False))\n'
