KAPPA = '"""Slide 7: kappa per state (one-vs-rest Fleiss), same numbers as the paper."""\nimport matplotlib\nmatplotlib.rcParams["svg.fonttype"] = "none"\nimport matplotlib.pyplot as plt\nfrom palette import STATE_COLORS\n\nKAPPA = {"productive": 0.74, "exploring": 0.66, "help-seeking": 0.79, "stalled": 0.61, "stalled-after-error": 0.58, "off-task": 0.84}\n\n\ndef draw(path="../slides/img/kappa_by_state.svg"):\n    fig, ax = plt.subplots(figsize=(9, 3.6))\n    states = [s for s in STATE_COLORS if s in KAPPA]\n    ax.bar(states, [KAPPA[s] for s in states], color=[STATE_COLORS[s] for s in states])\n    ax.axhline(0.71, ls="--", lw=1, color="k"); ax.text(len(states) - 0.5, 0.72, "overall 0.71", ha="right", fontsize=11)\n    ax.set_ylim(0, 1); ax.set_ylabel("κ")\n    for s in ("top", "right"):\n        ax.spines[s].set_visible(False)\n    fig.tight_layout(); fig.savefig(path, transparent=True); plt.close(fig)\n\n\nif __name__ == "__main__":\n    draw()\n'
TIMELINE = '"""Slide 6: P07 session as a state strip, revealed in 4 steps (one SVG per step)."""\nimport pandas as pd\nimport matplotlib\nmatplotlib.rcParams["svg.fonttype"] = "none"\nimport matplotlib.pyplot as plt\nfrom palette import STATE_COLORS\n\nSTEPS = [(0, 300, "first 5 minutes"), (0, 492, "first error"), (0, 1010, "the stall"), (0, 1320, "recovery")]\n\n\ndef strip(df, upto, path, caption):\n    fig, ax = plt.subplots(figsize=(10, 1.4))\n    for _, r in df[df.t0 < upto].iterrows():\n        ax.barh(0, min(r.t1, upto) - r.t0, left=r.t0, color=STATE_COLORS[r.state], height=0.8)\n    ax.set_xlim(0, 1320); ax.set_yticks([])\n    ax.set_xticks(range(0, 1321, 300), [f"{m} min" for m in range(0, 23, 5)])\n    ax.set_title(caption, loc="left", fontsize=12)\n    for s in ("top", "right", "left"):\n        ax.spines[s].set_visible(False)\n    fig.tight_layout(); fig.savefig(path, transparent=True); plt.close(fig)\n\n\nif __name__ == "__main__":\n    df = pd.read_csv("data/p07_states.csv")  # columns: t0, t1 (seconds), state\n    for i, (_, upto, cap) in enumerate(STEPS, 1):\n        strip(df, upto, f"slides/img/p07_step{i}.svg", cap)\n    print("wrote", len(STEPS), "frames")\n'
TRANS_BUG = 'import pandas as pd\nimport matplotlib.pyplot as plt\nfrom palette import STATE_COLORS\n\n\ndef draw(df, path):\n    """Slide 8: state -> next-state flow, bar per source state."""\n    nxt = df.assign(next=df.state.shift(-1)).dropna()\n    counts = nxt.groupby(["state", "next"]).size().unstack(fill_value=0)\n    order = [s for s in STATE_ORDER if s in counts.index]\n    share = counts.loc[order].div(counts.loc[order].sum(axis=1), axis=0)\n    ax = share.plot.barh(stacked=True, color=[STATE_COLORS.get(c, "#999999") for c in share.columns], figsize=(9, 4), width=0.8)\n    ax.set_xlabel("share of next window"); ax.legend(bbox_to_anchor=(1, 1), fontsize=9, frameon=False)\n    plt.tight_layout(); plt.savefig(path, transparent=True); plt.close()\n\n\nif __name__ == "__main__":\n    draw(pd.read_csv("data/p07_states.csv"), "slides/img/transitions.svg")\n'
TRANS_FIX = TRANS_BUG.replace('from palette import STATE_COLORS\n', 'from palette import STATE_COLORS\n\nSTATE_ORDER = list(STATE_COLORS)  # paper order; includes stalled-after-error\n', 1)
TESTS = 'import sys\nfrom pathlib import Path\nimport pandas as pd\n\nsys.path.insert(0, str(Path(__file__).parents[1] / "figures"))\nimport palette, timeline, transitions, kappa_bar  # noqa: E402\n\nSAMPLE = pd.DataFrame({"t0": [0, 300, 492, 1010], "t1": [300, 492, 1010, 1320],\n                       "state": ["productive", "exploring", "stalled-after-error", "productive"]})\n\n\ndef test_transition_figure(tmp_path):\n    transitions.draw(SAMPLE, tmp_path / "x.svg")\n    assert (tmp_path / "x.svg").stat().st_size > 1000\n\n\ndef test_palette_has_all_six_states():\n    assert len(palette.STATE_COLORS) == 6\n\n\ndef test_timeline_frame(tmp_path):\n    timeline.strip(SAMPLE, 600, tmp_path / "f.svg", "t")\n    assert (tmp_path / "f.svg").exists()\n\n\ndef test_kappa_states_match_palette():\n    assert set(kappa_bar.KAPPA) == set(palette.STATE_COLORS)\n'
