# =================================================================================== papert-lab-proto
PKG = '{\n  "name": "papert-lab-proto",\n  "private": true,\n  "version": "0.1.0",\n  "scripts": {"dev": "next dev", "build": "next build", "start": "next start", "lint": "next lint"},\n  "dependencies": {"next": "15.1.4", "react": "19.0.0", "react-dom": "19.0.0", "react-markdown": "^9.0.1"},\n  "devDependencies": {"typescript": "^5.7.3", "@types/react": "^19.0.0", "@types/node": "^22.10.0"}\n}\n'
PKG2 = PKG.replace('"react-markdown": "^9.0.1"', '"react-markdown": "^9.0.1", "nanoid": "^5.0.9"')
LAYOUT = 'import "./globals.css";\n\nexport const metadata = { title: "Papert Lab notebook" };\n\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang="en">\n      <body>{children}</body>\n    </html>\n  );\n}\n'
CSS_A = 'body { font-family: ui-sans-serif, system-ui; margin: 0; color: #1d1d1f; }\nmain { max-width: 760px; margin: 40px auto; padding: 0 16px; }\n'
CSS_B = CSS_A + '.cell { border-left: 3px solid #e5e5e5; padding: 6px 12px; margin: 14px 0; }\n.cell:focus-within { border-color: #4c72b0; }\n.chip { display: inline-block; font-size: 12px; background: #f1f1f4; border-radius: 10px; padding: 1px 8px; margin: 2px 4px 0 0; }\n.trail { font-size: 13px; color: #555; border-top: 1px dashed #ddd; margin-top: 8px; padding-top: 6px; }\n'
CSS_C = CSS_B + ':root { --accent: #3b5ba9; }\nh1 { font-weight: 650; letter-spacing: -0.01em; }\n.chip:hover { background: #e3e8f5; cursor: pointer; }\n.search { width: 100%; padding: 8px 10px; border: 1px solid #ddd; border-radius: 8px; }\n'
HOME1 = 'export default function Home() {\n  return (\n    <main>\n      <h1>Papert Lab</h1>\n      <p>A notebook that remembers where your thoughts came from.</p>\n    </main>\n  );\n}\n'
HOME2 = '"use client";\nimport Link from "next/link";\nimport { useNotebooks, newNotebook } from "@/lib/store";\n\nexport default function Home() {\n  const notebooks = useNotebooks();\n  return (\n    <main>\n      <h1>Papert Lab</h1>\n      <p>A notebook that remembers where your thoughts came from.</p>\n      <button onClick={() => newNotebook("Untitled notebook")}>New notebook</button>\n      <ul>{notebooks.map((n) => <li key={n.id}><Link href={`/notebook/${n.id}`}>{n.title}</Link> · {n.cells.length} cells</li>)}</ul>\n    </main>\n  );\n}\n'
STORE1 = '"use client";\nimport { useSyncExternalStore } from "react";\nimport { nanoid } from "nanoid";\n\nexport type Cell = { id: string; text: string; createdAt: string };\nexport type Notebook = { id: string; title: string; cells: Cell[] };\n\nconst KEY = "papert:notebooks";\nconst listeners = new Set<() => void>();\nconst read = (): Notebook[] => JSON.parse(localStorage.getItem(KEY) || "[]");\nconst write = (nb: Notebook[]) => { localStorage.setItem(KEY, JSON.stringify(nb)); listeners.forEach((l) => l()); };\n\nexport const useNotebooks = () => useSyncExternalStore((l) => (listeners.add(l), () => listeners.delete(l)), read, () => []);\nexport const newNotebook = (title: string) => write([...read(), { id: nanoid(8), title, cells: [] }]);\nexport const addCell = (nbId: string, text: string) =>\n  write(read().map((n) => (n.id === nbId ? { ...n, cells: [...n.cells, { id: nanoid(8), text, createdAt: new Date().toISOString() }] } : n)));\n'
STORE2 = STORE1.replace('export type Cell = { id: string; text: string; createdAt: string };', 'export type Source = { id: string; kind: "url" | "chat" | "cell" | "pdf"; title: string; ref: string; addedAt: string };\nexport type Cell = { id: string; text: string; createdAt: string; sources: string[] };  // source ids').replace('export type Notebook = { id: string; title: string; cells: Cell[] };', 'export type Notebook = { id: string; title: string; cells: Cell[]; sources: Source[] };').replace('cells: [] }]);', 'cells: [], sources: [] }]);').replace("createdAt: new Date().toISOString() }] } : n)));", "createdAt: new Date().toISOString(), sources: [] }] } : n)));\nexport const linkSource = (nbId: string, cellId: string, src: Omit<Source, \"id\" | \"addedAt\">) =>\n  write(read().map((n) => {\n    if (n.id !== nbId) return n;\n    const s = { ...src, id: nanoid(8), addedAt: new Date().toISOString() };\n    return { ...n, sources: [...n.sources, s], cells: n.cells.map((c) => (c.id === cellId ? { ...c, sources: [...c.sources, s.id] } : c)) };\n  }));")
NBPAGE1 = '"use client";\nimport { useState } from "react";\nimport ReactMarkdown from "react-markdown";\nimport { useNotebooks, addCell } from "@/lib/store";\n\nexport default function NotebookPage({ params }: { params: { id: string } }) {\n  const nb = useNotebooks().find((n) => n.id === params.id);\n  const [draft, setDraft] = useState("");\n  if (!nb) return <main>Notebook not found</main>;\n  return (\n    <main>\n      <h1>{nb.title}</h1>\n      {nb.cells.map((c) => <div key={c.id} className="cell"><ReactMarkdown>{c.text}</ReactMarkdown></div>)}\n      <textarea value={draft} onChange={(e) => setDraft(e.target.value)} placeholder="Write a thought (markdown)…" rows={3} style={{ width: "100%" }} />\n      <button onClick={() => { addCell(nb.id, draft); setDraft(""); }} disabled={!draft.trim()}>Add</button>\n    </main>\n  );\n}\n'
NBPAGE2 = NBPAGE1.replace('import { useNotebooks, addCell } from "@/lib/store";', 'import { useNotebooks, addCell } from "@/lib/store";\nimport { CellView } from "@/components/CellView";').replace('{nb.cells.map((c) => <div key={c.id} className="cell"><ReactMarkdown>{c.text}</ReactMarkdown></div>)}', '{nb.cells.map((c) => <CellView key={c.id} nb={nb} cell={c} />)}').replace('import ReactMarkdown from "react-markdown";\n', '')
CELLVIEW1 = '"use client";\nimport ReactMarkdown from "react-markdown";\nimport type { Cell, Notebook } from "@/lib/store";\n\nexport function CellView({ nb, cell }: { nb: Notebook; cell: Cell }) {\n  const srcs = cell.sources.map((id) => nb.sources.find((s) => s.id === id)).filter(Boolean);\n  return (\n    <div className="cell">\n      <ReactMarkdown>{cell.text}</ReactMarkdown>\n      <div>{srcs.map((s) => <span key={s!.id} className="chip" title={s!.ref}>{s!.kind}: {s!.title}</span>)}</div>\n    </div>\n  );\n}\n'
PASTE = '"use client";\nimport { linkSource } from "@/lib/store";\n\n// Paste a URL into a cell\'s source box -> a source card titled from the page <title> (via /api/title).\nexport async function addUrlSource(nbId: string, cellId: string, url: string) {\n  let title = url;\n  try {\n    const r = await fetch(`/api/title?url=${encodeURIComponent(url)}`);\n    if (r.ok) title = (await r.json()).title || url;\n  } catch {}\n  linkSource(nbId, cellId, { kind: "url", title, ref: url });\n}\n'
TITLE_API = 'import { NextResponse } from "next/server";\n\nexport async function GET(req: Request) {\n  const url = new URL(req.url).searchParams.get("url");\n  if (!url || !/^https?:\\/\\//.test(url)) return NextResponse.json({ title: null }, { status: 400 });\n  const html = await fetch(url, { headers: { "user-agent": "papert-lab-proto" } }).then((r) => r.text()).catch(() => "");\n  const m = html.match(/<title[^>]*>([^<]{1,200})<\\/title>/i);\n  return NextResponse.json({ title: m ? m[1].trim() : null });\n}\n'
TRAIL1 = '"use client";\nimport type { Notebook } from "@/lib/store";\n\n// Walk back from a cell through the cells and sources it cites ("where did this thought come from").\nexport function trail(nb: Notebook, cellId: string, depth = 0): string[] {\n  const c = nb.cells.find((x) => x.id === cellId);\n  if (!c) return [];\n  const out: string[] = [];\n  for (const sid of c.sources) {\n    const s = nb.sources.find((x) => x.id === sid);\n    if (!s) continue;\n    out.push(`${"  ".repeat(depth)}${s.kind}: ${s.title}`);\n    if (s.kind === "cell") out.push(...trail(nb, s.ref, depth + 1));\n  }\n  return out;\n}\n\nexport function TrailView({ nb, cellId }: { nb: Notebook; cellId: string }) {\n  const lines = trail(nb, cellId);\n  if (!lines.length) return null;\n  return <pre className="trail">{lines.join("\\n")}</pre>;\n}\n'
TRAIL2 = TRAIL1.replace('export function trail(nb: Notebook, cellId: string, depth = 0): string[] {\n  const c = nb.cells.find((x) => x.id === cellId);\n  if (!c) return [];', 'export function trail(nb: Notebook, cellId: string, depth = 0, seen = new Set<string>()): string[] {\n  // two cells citing each other used to recurse forever (2026-02-10)\n  if (seen.has(cellId)) return [`${"  ".repeat(depth)}(cycle)`];\n  seen.add(cellId);\n  const c = nb.cells.find((x) => x.id === cellId);\n  if (!c) return [];').replace('out.push(...trail(nb, s.ref, depth + 1));', 'out.push(...trail(nb, s.ref, depth + 1, seen));')
CELLVIEW2 = CELLVIEW1.replace('import type { Cell, Notebook } from "@/lib/store";', 'import type { Cell, Notebook } from "@/lib/store";\nimport { TrailView } from "@/components/Trail";').replace('    </div>\n  );\n}', '      <TrailView nb={nb} cellId={cell.id} />\n    </div>\n  );\n}')
CHATIMPORT = '"use client";\nimport { linkSource, addCell, type Notebook } from "@/lib/store";\n\n// Import a ChatGPT export (conversations.json): each conversation becomes a "chat" source; the first user message\n// becomes a cell that cites it, so a notebook can start from what you already asked.\nexport function importChatGPT(nb: Notebook, json: any[]) {\n  let n = 0;\n  for (const conv of json) {\n    const msgs = Object.values(conv.mapping || {}).map((m: any) => m.message).filter((m: any) => m && m.author?.role === "user");\n    const first = msgs.sort((a: any, b: any) => (a.create_time || 0) - (b.create_time || 0))[0];\n    if (!first) continue;\n    const text = (first.content?.parts || []).join(" ").slice(0, 500);\n    addCell(nb.id, `> ${text}`);\n    n++;\n  }\n  return n;\n}\n'
SEARCH = '"use client";\nimport type { Notebook } from "@/lib/store";\n\nexport function search(nb: Notebook, q: string) {\n  const t = q.trim().toLowerCase();\n  if (!t) return { cells: [], sources: [] };\n  return {\n    cells: nb.cells.filter((c) => c.text.toLowerCase().includes(t)),\n    sources: nb.sources.filter((s) => (s.title + " " + s.ref).toLowerCase().includes(t)),\n  };\n}\n'
SEED = '[\n  {\n    "id": "demo0001",\n    "title": "TutorTrace reading notes (demo)",\n    "cells": [\n      {"id": "c1", "text": "Stalls are often *silent*: students don\'t ask for help when stuck.", "createdAt": "2026-02-12T02:10:00Z", "sources": ["s1"]},\n      {"id": "c2", "text": "So detect stalls from telemetry instead of waiting for a help request.", "createdAt": "2026-02-12T02:12:00Z", "sources": ["s2", "s3"]},\n      {"id": "c3", "text": "Open question: flag the TA, or nudge the student directly?", "createdAt": "2026-02-12T02:15:00Z", "sources": ["s4"]}\n    ],\n    "sources": [\n      {"id": "s1", "kind": "pdf", "title": "Productive Struggle or Silent Stalling? (Ostrowski et al. 2025)", "ref": "papers/ostrowski2025.pdf", "addedAt": "2026-02-12T02:09:00Z"},\n      {"id": "s2", "kind": "cell", "title": "Stalls are often silent", "ref": "c1", "addedAt": "2026-02-12T02:12:00Z"},\n      {"id": "s3", "kind": "chat", "title": "ChatGPT: features for detecting stuck students", "ref": "chatgpt:demo", "addedAt": "2026-02-12T02:12:00Z"},\n      {"id": "s4", "kind": "cell", "title": "detect stalls from telemetry", "ref": "c2", "addedAt": "2026-02-12T02:15:00Z"}\n    ]\n  }\n]\n'
