# =================================================================================== beat-tools
LAYOUT_MD = '# Sample library layout\n\n~/Music/Samples/<pack name>/ as downloaded; never edit inside a pack folder by hand.\n\n- Packs: Cymatics - Oracle, KSHMR Vol 4, Lofi Keys Pack, Splice - Trap Essentials, Unison Drum Kit, free_808s\n- FL Studio projects: ~/Music/FL Projects/<yyyy-mm> <name>.flp\n- Weekly zip of FL projects to ~/Music/backups (flp_backup.sh)\n'
BACKUP = '#!/bin/zsh\n# Zip this week\'s FL Studio projects (+ their audio clips folder) to ~/Music/backups.\nset -e\nsrc="$HOME/Music/FL Projects"\ndst="$HOME/Music/backups"\nmkdir -p "$dst"\nstamp=$(date +%Y-%m-%d)\ncd "$src"\nfind . -name "*.flp" -mtime -7 -print0 | xargs -0 zip -q "$dst/flp-$stamp.zip"\necho "wrote $dst/flp-$stamp.zip ($(unzip -l "$dst/flp-$stamp.zip" | tail -1 | awk \'{print $2}\') files)"\n'
LIST = '"""Count samples per pack and rough kind (from the file name)."""\nimport collections, sys\nfrom pathlib import Path\n\nKINDS = ["kick", "snare", "clap", "hat", "perc", "808", "bass", "pad", "pluck", "lead", "vox", "fx", "loop"]\n\nroot = Path(sys.argv[1] if len(sys.argv) > 1 else Path.home() / "Music" / "Samples")\nfor pack in sorted(p for p in root.iterdir() if p.is_dir()):\n    c = collections.Counter()\n    for f in pack.rglob("*"):\n        if f.suffix.lower() == ".wav":\n            name = f.stem.lower()\n            c[next((k for k in KINDS if k in name), "other")] += 1\n    print(f"{pack.name:<28} {sum(c.values()):>5}  " + " ".join(f"{k}:{n}" for k, n in c.most_common(5)))\n'
RENAME1 = '"""Normalize sample file names: <kind>_<descriptor>_<nn>[_<key>][_<bpm>].wav (dry run unless --apply)."""\nimport argparse, csv, re\nfrom pathlib import Path\n\nKINDS = ["kick", "snare", "clap", "hat", "perc", "bass", "pluck", "pad", "lead", "vox", "fx", "loop"]\nALIAS = {"hihat": "hat", "hh": "hat", "808": "bass", "vocal": "vox", "sfx": "fx", "shaker": "perc", "rim": "perc"}\nKEY = re.compile(r"(?<![a-z])([a-g](?:#|b)?(?:m|min|maj)?)(?![a-z])", re.I)\nBPM = re.compile(r"(?<!\\d)(\\d{2,3})\\s*(?:bpm)?(?!\\d)", re.I)\nVENDOR = re.compile(r"^(kshmr|cymatics|splice|unison)\\s*(vol\\s*\\d+)?\\s*[-_ ]*", re.I)\n\n\ndef parse(stem):\n    s = VENDOR.sub("", stem.lower())\n    s = re.sub(r"[()\\[\\]]", " ", s)\n    toks = [t for t in re.split(r"[\\s_\\-]+", s) if t]\n    kind = next((ALIAS.get(t, t) for t in toks if ALIAS.get(t, t) in KINDS), "fx")\n    bpm = next((int(m.group(1)) for t in toks if (m := BPM.fullmatch(t)) and 60 <= int(m.group(1)) <= 200), None)\n    key = next((t.lower().replace("min", "m") for t in toks if KEY.fullmatch(t) and t.lower() not in ("a", "b")), None)\n    num = next((int(t) for t in toks if t.isdigit() and int(t) != bpm and len(t) <= 2), 1)\n    desc = [t for t in toks if t not in KINDS and t not in ALIAS and not t.isdigit() and t not in ("loop", "bpm") and t != key]\n    return kind, "-".join(desc[:2]) or "x", num, key, bpm\n\n\ndef new_name(path):\n    kind, desc, num, key, bpm = parse(path.stem)\n    parts = [kind, desc, f"{num:02d}"] + ([key] if key else []) + ([str(bpm)] if bpm else [])\n    return "_".join(parts) + ".wav"\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("root", type=Path)\n    ap.add_argument("--apply", action="store_true")\n    ap.add_argument("--log", default="rename_log.csv")\n    a = ap.parse_args()\n    rows = []\n    for p in sorted(a.root.rglob("*")):\n        if p.suffix.lower() != ".wav":\n            continue\n        q = p.with_name(new_name(p))\n        if q.name == p.name:\n            continue\n        rows.append((str(p), str(q)))\n        print(f"{p.name}  ->  {q.name}")\n        if a.apply:\n            p.rename(q)\n    with open(a.log, "a", newline="") as f:\n        csv.writer(f).writerows(rows)\n    print(f"{len(rows)} files {\'renamed\' if a.apply else \'would be renamed (dry run)\'}")\n\n\nif __name__ == "__main__":\n    main()\n'
RENAME2 = RENAME1.replace('KINDS = ["kick", "snare", "clap", "hat", "perc", "bass", "pluck", "pad", "lead", "vox", "fx", "loop"]\nALIAS = {', 'KINDS = ["kick", "snare", "clap", "hat", "perc", "bass", "keys", "pluck", "pad", "lead", "vox", "fx", "loop"]\nALIAS = {"rhodes": "keys", "piano": "keys", "ep": "keys", ')
UNDO = '\n\ndef undo(log):\n    """Rename files back using the old,new pairs in the log (newest first)."""\n    pairs = list(csv.reader(open(log)))\n    for old, new in reversed(pairs):\n        if Path(new).exists() and not Path(old).exists():\n            Path(new).rename(old)\n    print(f"restored {len(pairs)} files")\n'
RENAME3 = RENAME2.replace('\n\ndef main():', UNDO + '\n\ndef main():').replace('    ap.add_argument("--log", default="rename_log.csv")\n    a = ap.parse_args()\n', '    ap.add_argument("--log", default="rename_log.csv")\n    ap.add_argument("--undo", action="store_true", help="restore names from --log")\n    a = ap.parse_args()\n    if a.undo:\n        return undo(a.log)\n')
RENAME4 = RENAME3.replace('def new_name(path):\n    kind, desc, num, key, bpm = parse(path.stem)', 'def new_name(path, detect=False):\n    kind, desc, num, key, bpm = parse(path.stem)\n    if detect and bpm is None:\n        from .bpm import estimate\n        bpm = estimate(path)').replace('        q = p.with_name(new_name(p))', '        q = p.with_name(new_name(p, detect=a.detect_bpm))').replace('    ap.add_argument("--apply", action="store_true")', '    ap.add_argument("--apply", action="store_true")\n    ap.add_argument("--detect-bpm", action="store_true", help="estimate BPM for loops without one in the name")')
RENAME5 = RENAME4.replace('        q = p.with_name(new_name(p, detect=a.detect_bpm))\n        if q.name == p.name:\n            continue', '        q = p.with_name(new_name(p, detect=a.detect_bpm))\n        if q.name == p.name:\n            continue\n        taken = {r[1] for r in rows}\n        n = 2\n        while q.exists() or str(q) in taken:  # two samples normalizing to one name used to overwrite each other\n            kind, desc, *rest = q.stem.split("_")\n            q = q.with_name("_".join([kind, desc, f"{n:02d}"] + rest[1:]) + q.suffix); n += 1')
BPM_PY = '"""Tempo estimate for loops (librosa beat tracker), folded into 70-180 BPM."""\nimport librosa\n\n\ndef fold(bpm, lo=70, hi=180):\n    while bpm < lo:\n        bpm *= 2\n    while bpm > hi:\n        bpm /= 2\n    return bpm\n\n\ndef estimate(path, sr=22050):\n    y, sr = librosa.load(path, sr=sr, mono=True)\n    if len(y) < 2 * sr:\n        return None  # one-shots: no tempo\n    onset = librosa.onset.onset_strength(y=y, sr=sr)\n    tempo = librosa.feature.tempo(onset_envelope=onset, sr=sr, aggregate=None)\n    return int(round(fold(float(tempo.mean()))))\n'
