def user_obj():
    u = dict(U)
    for k in ('followers', 'following{/other_user}', 'gists{/gist_id}', 'starred{/owner}{/repo}', 'subscriptions', 'organizations', 'repos',
              'events{/privacy}', 'received_events'):
        u[k.split('{')[0] + '_url'] = f'https://api.github.com/users/{OWNER}/{k}'
    return u


